// Native monochrome lyric glyphs rasterized for the 128x64 OLED.
// Korean uses Apple SD Gothic Neo; Latin uses Arial Rounded Bold.
// All glyphs are stored in flash and need no font files at runtime.
struct HangulGlyph {
  uint16_t codePoint;
  uint8_t bitmap[32];  // native 16x16, two bytes per row
};

struct LatinGlyph {
  uint8_t codePoint;
  uint8_t advance;
  uint8_t bitmap[60];  // native 18x20, three bytes per row
};

